// Extract order payload
const body = $input.first().json.body || $input.first().json;

const orderId = body.orderId || body.id;
const orderNumber = body.orderNumber || 'ORD-UNKNOWN';
const totalAmount = Number(body.totalAmount) || 0;
const customer = body.customer || {};
const items = body.items || [];
const pastOrdersCount = Number(customer.pastOrdersCount) || 0;
const pastDeliveredCount = Number(customer.pastDeliveredCount) || 0;
const pastRtoCount = Number(customer.pastRtoCount) || 0;

// Deterministic Risk Engine
let score = 15; // Baseline risk
const riskFactors = [];

// 1. Phone number sanity (India 10-digit check)
const phoneDigits = (customer.phone || '').replace(/\D/g, '');
if (!phoneDigits || phoneDigits.length < 10 || /^(\d)\1{9}$/.test(phoneDigits)) {
  score += 30;
  riskFactors.push('Unverified or repetitive phone number');
}

// 2. Shipping address verification
const address = customer.address || '';
const pincode = customer.pincode || '';
if (!address || address.trim().length < 15) {
  score += 25;
  riskFactors.push('Incomplete or brief shipping address');
}
if (!pincode || pincode.trim().length !== 6 || !/^\d{6}$/.test(pincode.trim())) {
  score += 20;
  riskFactors.push('Missing or invalid 6-digit postal code');
}

// 3. Buyer order history & return ratio
if (pastRtoCount > 0) {
  const rtoPenalty = Math.min(pastRtoCount * 25, 45);
  score += rtoPenalty;
  riskFactors.push(`Buyer has ${pastRtoCount} recorded return-to-origin (RTO) failures`);
} else if (pastOrdersCount === 0) {
  if (totalAmount > 3000) {
    score += 15;
    riskFactors.push('First-time buyer with high COD cart value (> ₹3,000)');
  }
} else if (pastDeliveredCount > 2 && pastRtoCount === 0) {
  score = Math.max(5, score - 20);
  riskFactors.push('Trusted repeat customer with 100% past delivery success');
}

// 4. Cart composition anomaly
if (items.length > 5 && totalAmount < 1000) {
  score += 15;
  riskFactors.push('High item quantity with unusually low basket value');
}

score = Math.min(Math.max(score, 5), 98);

let recommendation = 'PROCEED';
let riskLevel = 'LOW';
if (score >= 70) {
  recommendation = 'MANUAL_REVIEW';
  riskLevel = 'HIGH';
} else if (score >= 40) {
  recommendation = 'REQUEST_CONFIRMATION';
  riskLevel = 'MEDIUM';
}

return {
  json: {
    orderId,
    orderNumber,
    riskScore: score,
    riskLevel,
    recommendation,
    reasons: riskFactors,
    requiresAction: recommendation !== 'PROCEED',
    suggestedAction: recommendation === 'REQUEST_CONFIRMATION' ? 'EMAIL_CONFIRMATION' : 'MERCHANT_MANUAL_REVIEW',
    analysisPrompt: `Analyze COD order ${orderNumber} for buyer ${customer.name || 'Customer'}. Order total is ₹${totalAmount}. Risk score is ${score}/100. Factors: ${riskFactors.join(', ')}. Provide a 2-sentence risk summary.`
  }
};

