const prev = $('Deterministic Risk Scoring').first().json;
const groqRes = $input.first().json;

let aiSummary = '';
try {
  aiSummary = groqRes.choices?.[0]?.message?.content?.trim() || '';
} catch (e) {
  aiSummary = `Deterministic risk evaluation of ${prev.riskScore}/100 due to: ${prev.reasons.join(', ')}`;
}

if (!aiSummary) {
  aiSummary = `Order flagged with risk score ${prev.riskScore}/100. Verification recommended based on risk triggers.`;
}

return {
  json: {
    orderId: prev.orderId,
    orderNumber: prev.orderNumber,
    riskScore: prev.riskScore,
    riskLevel: prev.riskLevel,
    recommendation: prev.recommendation,
    reasons: prev.reasons,
    aiAnalysis: {
      summary: aiSummary,
      model: 'llama-3.3-70b-versatile',
      confidence: prev.riskScore > 65 ? 0.91 : 0.84
    },
    requiresAction: prev.requiresAction,
    suggestedAction: prev.suggestedAction,
    timestamp: new Date().toISOString()
  }
};
